import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as s,o as t,af as r,b as d,w as a,a as c,G as h,ag as l}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const A=JSON.parse('{"title":"Model Architecture (Bridge)","description":"A one-line positioning table for Transformer / Attention / RoPE / MoE / KV cache — application engineers do not need the derivations, but must be able to translate architecture terms into engineering variables of context length, inference cost, and multimodal paths; derivations belong to Learn LLM.","frontmatter":{"title":"Model Architecture (Bridge)","description":"A one-line positioning table for Transformer / Attention / RoPE / MoE / KV cache — application engineers do not need the derivations, but must be able to translate architecture terms into engineering variables of context length, inference cost, and multimodal paths; derivations belong to Learn LLM.","domain":"tech","tags":["tech","model-lifecycle","bridge","architecture"],"navOrder":12,"topicId":"architecture","layer":"1","status":"bridge","nodeType":"concept","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/07-attention"}],"prerequisites":["llm-mental-model"],"next":["data-pretraining-scaling"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/01-model-lifecycle/architecture.md","filePath":"tech/01-model-lifecycle/architecture.md","lastUpdated":1791123021000}'),p={name:"tech/01-model-lifecycle/architecture.md"};function u(g,e,f,m,b,v){const n=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=r('<blockquote><p><strong>Group</strong>: 01 · Model Lifecycle (bridge group) | <strong>Exit of the group above</strong>: you can decide knowledge ownership and pick the lowest-complexity option for a need (00-map group) | <strong>Exit of this page</strong>: you can translate vendor-launch architecture terms (long context, MoE, cache pricing) into engineering variables of context length, inference cost, and input modality <strong>Prerequisites</strong>: <a href="./llm-mental-model.html">The LLM Mental Model (Bridge)</a> | <strong>Next</strong>: <a href="./data-pretraining-scaling.html">Data, Pretraining, and Scaling (Bridge)</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: application engineers do not need to derive Attention, but they do need <strong>position awareness</strong> — architecture is frozen at pretraining and directly determines context length, inference cost, and the multimodal path, all three of which show up on your API bill and in your selection spreadsheet. This page gives each component a one-line &quot;what it is / what decision it touches&quot; position; derivations and from-scratch implementations belong to Learn LLM chapters 7, 9, and 20.</p><h3 id="one-line-positioning-table" tabindex="-1">One-line positioning table <a class="header-anchor" href="#one-line-positioning-table" aria-label="Permalink to &quot;One-line positioning table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>What it is (one line)</th><th>What decision it touches</th></tr></thead><tbody><tr><td>Transformer</td><td>The self-attention-based sequence backbone; the common foundation of modern LLMs</td><td>Switching models = swapping a set of weights with an unchanged interface; far cheaper than switching paradigms</td></tr><tr><td>Attention</td><td>The mechanism where tokens weight each other pairwise; the causal mask enables token-by-token generation</td><td>Attention computation grows with sequence length — the reason long context costs more</td></tr><tr><td>Positional encoding (RoPE)</td><td>Rotates position information into queries/keys so the model senses token order</td><td>The source of a model&#39;s advertised context length; window extension is a recurring release variable</td></tr><tr><td>MoE (Mixture of Experts)</td><td>Activates only a fraction of expert parameters per layer: large total, small per-token activation</td><td>Parameter count decouples from per-token cost; an architectural root of vendor pricing differences</td></tr><tr><td>KV cache and MQA / GQA</td><td>Caches attention keys/values at inference, plus variants that shrink that cache</td><td>The prefill/decode cost structure and prompt-prefix cache pricing</td></tr></tbody></table><h3 id="why-position-awareness-not-derivation-ability" tabindex="-1">Why position awareness, not derivation ability <a class="header-anchor" href="#why-position-awareness-not-derivation-ability" aria-label="Permalink to &quot;Why position awareness, not derivation ability&quot;">​</a></h3>',6)),(t(),d(l,null,{default:a(()=>[h(n,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20S%20%5B%22Architecture%20components%20(frozen%20at%20pretraining)%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22Attention%20%2F%20positional%20encoding%22%5D%0A%20%20%20%20%20%20%20%20A2%5B%22MoE%20%2F%20KV%20cache%20variants%22%5D%0A%20%20%20%20%20%20%20%20A3%5B%22Multimodal%20projection%20layers%22%5D%0A%20%20%20%20end%0A%20%20%20%20A1%20--%3E%20P1%5B%22Context%20length%22%5D%0A%20%20%20%20A2%20--%3E%20P2%5B%22Inference%20cost%22%5D%0A%20%20%20%20A3%20--%3E%20P3%5B%22Available%20input%20modalities%22%5D%0A%20%20%20%20P1%20--%3E%20O%5B%22Interface%20properties%20you%20see%20on%20the%20API%22%5D%0A%20%20%20%20P2%20--%3E%20O%0A%20%20%20%20P3%20--%3E%20O%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>Architecture is where the left chain freezes physical constraints into interface properties: after training ends, nobody can change this model&#39;s window assumptions or expert routing — you wait for the vendor&#39;s next version. Architectural knowledge therefore takes the engineering form of &quot;decoding ability when reading release notes and pricing pages&quot;, not write ability. A vendor&#39;s &quot;longer context&quot; or &quot;cheaper tier&quot; is almost always an architecture variable — but the landing constraints are whatever the vendor documents say.</p><h2 id="_2-when-to-hop" tabindex="-1">2. When to Hop <a class="header-anchor" href="#_2-when-to-hop" aria-label="Permalink to &quot;2. When to Hop&quot;">​</a></h2><p>This page has no runnable artifact; route via this table:</p><table tabindex="0"><thead><tr><th>Symptom / question</th><th>Where to go</th><th>Why</th></tr></thead><tbody><tr><td>Want a hand-written Attention, why the causal mask exists</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/07-attention" target="_blank" rel="noreferrer">chapter 7</a></td><td>The canonical from-scratch Transformer</td></tr><tr><td>KV cache, quantization, prefill/decode cost models</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/09-inference-cache" target="_blank" rel="noreferrer">chapter 9</a></td><td>Engineering detail of inference optimization</td></tr><tr><td>MLA / MoE accounting / modern architecture topics</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/20-deepseek" target="_blank" rel="noreferrer">chapter 20</a></td><td>DeepSeek-family architecture special topic</td></tr><tr><td>How API billing and prefix-cache discounts work</td><td>This repo&#39;s <a href="./../02-inference-interface/model-api.html">Model API contract</a></td><td>Application-side consumption lives here</td></tr><tr><td>How much context a long session should carry</td><td>This repo&#39;s <a href="./../03-context/">03-context group</a></td><td>Context trade-offs are this repo&#39;s main line</td></tr><tr><td>Impact of a vendor&#39;s new architecture version on production</td><td>This repo&#39;s <a href="./../08-production/">08-production group</a></td><td>Version-upgrade regression is an operations problem</td></tr></tbody></table><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>One-paragraph positioning: Transformer replaced recurrence with self-attention for training parallelism, at the price of attention cost growing with length; RoPE determines how far the model can extrapolate context; MoE decouples &quot;total parameters&quot; from &quot;per-call computation&quot; via sparse activation; KV cache turns decode from recomputation into lookup. Those four sentences are all the architecture an application engineer needs — why scaled dot-product divides by √d, the complex-number form of RoPE, and expert-routing load balancing are derived step by step in Learn LLM chapters 7, 9, and 20 (retrievedAt 2026-09-01); this repo does not copy them.</p><h2 id="_4-engineering-decision-impact" tabindex="-1">4. Engineering Decision Impact <a class="header-anchor" href="#_4-engineering-decision-impact" aria-label="Permalink to &quot;4. Engineering Decision Impact&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Engineering decision</th><th>Architectural fact</th><th>Engineering action</th></tr></thead><tbody><tr><td>Long-session cost estimation</td><td>Attention and KV cache volume grow with length</td><td>Summarize and prune long history; watch vendor prefix-cache pricing</td></tr><tr><td>Model family selection</td><td>Dense and MoE have different cost structures</td><td>Tier by task; compare actual per-task cost, not parameter count</td></tr><tr><td>Context window upgrade</td><td>Window extension often changes behavior</td><td>Run regression evaluation before switching</td></tr><tr><td>Multimodal intake</td><td>Images enter token space via projection and are billed per token</td><td>Budget in tokens, not pixels or resolution</td></tr><tr><td>Local / edge deployment</td><td>Quantized variants shift the accuracy-cost balance</td><td>The math belongs to Learn LLM chapter 9; the selection decision to this repo&#39;s 02-inference-interface group</td></tr></tbody></table><p>Maintenance rule (in place of runbooks): when Learn LLM chapters 7/9/20 change structure, re-verify this page&#39;s deep links and update <code>lastVerified</code>; this page does not maintain a per-vendor adoption matrix of architectures — that drifts with versions; defer to each vendor&#39;s model documentation.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><table tabindex="0"><thead><tr><th>Level</th><th>What to read</th><th>Why this order</th></tr></thead><tbody><tr><td>Beginner</td><td>This page&#39;s positioning table + the <a href="./index.html">group guide</a></td><td>Build the &quot;component → interface property&quot; map first</td></tr><tr><td>Builder</td><td>This repo&#39;s <a href="./../02-inference-interface/model-api.html">Model API contract</a></td><td>Consume these architectural properties at the interface layer</td></tr><tr><td>Operator</td><td><a href="./../08-production/cost-performance.html">Cost and performance</a></td><td>Bring architecture variables into cost governance</td></tr><tr><td>Researcher</td><td>Learn LLM chapters 7, 9, 20 + the three original papers</td><td>Descend to mechanism and derivation</td></tr></tbody></table><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Level</th><th>Canonical URL</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>Learn LLM ch. 7 · Transformer</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/07-attention" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/07-attention</a></td><td>From-scratch Attention / causal mask / multi-head</td><td>Hand-write a Transformer block</td></tr><tr><td>Learn LLM ch. 9 · Inference and quantization</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/09-inference-cache" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/09-inference-cache</a></td><td>Engineering detail of RoPE, KV cache, MQA/GQA, quantization</td><td>Understand the inference cost structure</td></tr><tr><td>Learn LLM ch. 20 · DeepSeek special topic</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/20-deepseek" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/20-deepseek</a></td><td>MLA / MoE accounting and modern architecture evolution</td><td>Optional extension reading</td></tr><tr><td>Attention Is All You Need (Vaswani et al., 2017)</td><td>L4</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">https://arxiv.org/abs/1706.03762</a></td><td>The original Transformer paper</td><td>Read the attention section</td></tr><tr><td>RoFormer (Su et al., 2021)</td><td>L4</td><td><a href="https://arxiv.org/abs/2104.09864" target="_blank" rel="noreferrer">https://arxiv.org/abs/2104.09864</a></td><td>Where RoPE positional encoding was introduced</td><td>Read the rotary section</td></tr><tr><td>Switch Transformers (Fedus et al., 2021)</td><td>L4</td><td><a href="https://arxiv.org/abs/2101.03961" target="_blank" rel="noreferrer">https://arxiv.org/abs/2101.03961</a></td><td>The representative sparse-MoE work</td><td>Read the expert-routing section</td></tr></tbody></table><p>(Learn LLM chapters verified via its chapter index; arXiv links are stable abs URLs; retrievedAt 2026-09-01.)</p><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if a decision truly requires architectural derivation to get right (e.g. implementing an attention kernel yourself), it belongs to Learn LLM or an inference-engine team, not this page — sink the claim instead of expanding here.</li><li>Open: vendor adoption of MQA / GQA / MLA and long-context extrapolation drifts quickly with versions; this page keeps no adoption matrix — defer to each vendor&#39;s model card and pricing page.</li></ul><h3 id="where-learn-ai-stops-where-to-continue" tabindex="-1">Where learn-ai stops / where to continue <a class="header-anchor" href="#where-learn-ai-stops-where-to-continue" aria-label="Permalink to &quot;Where learn-ai stops / where to continue&quot;">​</a></h3><ul><li>Mechanism and derivation of Attention, RoPE, MoE: Learn LLM chapters 7, 9, 20 — this repo stops here.</li><li>Consume architectural properties at the interface layer: this repo&#39;s <a href="./../02-inference-interface/">02-inference-interface group</a>.</li><li>Next page in this group: <a href="./data-pretraining-scaling.html">Data, Pretraining, and Scaling (Bridge)</a>.</li></ul>',19))])}const k=i(p,[["render",u]]);export{A as __pageData,k as default};
